$paymentBlocked=str_contains($flash,'Décaissement bloqué');
$paymentChecks=[];
if($paymentBlocked){
    // The service currently returns one message per failed payment; split its checks
    // for accessible display without changing the server-side authorization.
    $parts=explode(' : ',$flash,2);
    $heading=trim($parts[0]);
    $details=$parts[1]??'';
    $details=preg_replace('/\\.?\\s*Régularisez sa fiche avant paiement\\.?$/u','',$details);
    foreach(explode(' ; ',$details) as $check){
        $check=trim($check," .;\\t\\n");
        if($check!=='')$paymentChecks[]=$check;
    }
}
